// Characters and NPCs: 16x24 frames, laid out as (3 animation frames) x (4 facings) per actor.
//
// Frame columns: 0 = standing, 1 = left step, 2 = right step.
// Rows: south, north, east, west - the same order the Direction type uses in the shared package.
// The west facing is generated by mirroring the east facing: a documented, deterministic
// transformation, not a second hand-drawn sprite that could drift out of sync.
import { PixelCanvas } from './pixelCanvas.mjs';
import { PALETTE } from './palette.mjs';

export const ACTOR_FRAME_WIDTH = 16;
export const ACTOR_FRAME_HEIGHT = 24;
export const ACTOR_FRAMES = 3;
export const ACTOR_FACINGS = ['south', 'north', 'east', 'west'];

/** Order of the actors inside actors.png. The TypeScript manifest mirrors this list. */
export const ACTOR_ORDER = ['player', 'villager'];

export const ACTOR_PALETTES = {
  player: {
    skin: PALETTE.skinPlayer,
    hair: PALETTE.hairPlayer,
    shirt: PALETTE.shirtPlayer,
    shirtDark: PALETTE.shirtPlayerDark,
    pants: PALETTE.pantsPlayer,
    hat: null,
  },
  villager: {
    skin: PALETTE.skinVillager,
    hair: PALETTE.hairVillager,
    shirt: PALETTE.shirtVillager,
    shirtDark: PALETTE.shirtVillagerDark,
    pants: PALETTE.pantsVillager,
    hat: PALETTE.hatVillager,
  },
};

/**
 * Paints one frame of an actor.
 *
 * The layout is fixed and documented so the sprite-sheet rectangles in the TypeScript manifest stay
 * verifiable: head rows 2-8, torso rows 9-15, legs rows 16-20, boots rows 21-22, inside a 16x24 box.
 */
export function paintActorFrame(actorName, facing, frame) {
  const palette = ACTOR_PALETTES[actorName];
  const canvas = new PixelCanvas(ACTOR_FRAME_WIDTH, ACTOR_FRAME_HEIGHT);
  const side = facing === 'east';
  const facingAway = facing === 'north';

  // Walk cycle: frame 1 lifts the left leg and drops the right arm, frame 2 mirrors that.
  const leftLegRaised = frame === 1;
  const rightLegRaised = frame === 2;
  const armSwing = frame === 1 ? 1 : frame === 2 ? -1 : 0;

  // ---- shadow (drawn first, and soft enough that the outline pass ignores it) ----
  canvas.fillEllipse(8, 22.5, 5, 1.5, PALETTE.shadow);

  // ---- legs and boots ----
  const legs = side
    ? [
        { x: 7, raised: rightLegRaised, front: true },
        { x: 5, raised: leftLegRaised, front: false },
      ]
    : [
        { x: 5, raised: leftLegRaised, front: false },
        { x: 9, raised: rightLegRaised, front: false },
      ];
  for (const leg of legs) {
    const legColor = leg.front ? palette.pants : shade(palette.pants, 0.85);
    const bottom = leg.raised ? 19 : 21;
    canvas.fillRect(leg.x, 16, 2, bottom - 15, legColor);
    canvas.fillRect(leg.x - (side ? 0 : 0), bottom, 3, 1, PALETTE.boots);
    canvas.fillRect(leg.x, bottom + 1, 2, 1, PALETTE.boots);
  }

  // ---- torso ----
  const torsoX = side ? 6 : 4;
  const torsoWidth = side ? 5 : 8;
  canvas.fillRect(torsoX, 9, torsoWidth, 7, palette.shirt);
  canvas.fillRect(torsoX, 14, torsoWidth, 2, palette.shirtDark);
  if (!facingAway) {
    // Collar line, so front and back are distinguishable at a glance.
    canvas.fillRect(torsoX + 1, 9, torsoWidth - 2, 1, palette.shirtDark);
  }

  // ---- arms ----
  if (side) {
    canvas.fillRect(10, 10 + armSwing, 2, 4, palette.shirt);
    canvas.fillRect(10, 14 + armSwing, 2, 2, palette.skin);
  } else {
    canvas.fillRect(3, 10 - armSwing, 2, 4, palette.shirtDark);
    canvas.fillRect(3, 14 - armSwing, 2, 2, palette.skin);
    canvas.fillRect(11, 10 + armSwing, 2, 4, palette.shirtDark);
    canvas.fillRect(11, 14 + armSwing, 2, 2, palette.skin);
  }

  // ---- head ----
  const headX = side ? 6 : 4;
  const headWidth = side ? 5 : 8;
  canvas.fillRect(headX, 3, headWidth, 6, palette.skin);
  if (facingAway) {
    canvas.fillRect(headX, 2, headWidth, 5, palette.hair);
    canvas.fillRect(headX - 1, 4, headWidth + 2, 3, palette.hair);
  } else if (side) {
    canvas.fillRect(headX + 2, 2, 3, 4, palette.hair);
    canvas.fillRect(headX + 4, 4, 1, 4, palette.hair);
    canvas.set(10, 6, PALETTE.outline); // single eye, facing east
  } else {
    canvas.fillRect(headX, 2, headWidth, 3, palette.hair);
    canvas.fillRect(headX - 1, 3, 2, 3, palette.hair);
    canvas.fillRect(headX + headWidth - 1, 3, 2, 3, palette.hair);
    canvas.set(6, 6, PALETTE.outline);
    canvas.set(9, 6, PALETTE.outline);
  }

  // ---- hat (villager only): a wide brim that also hides the hairline ----
  if (palette.hat) {
    canvas.fillRect(headX - 2, 2, headWidth + 4, 2, palette.hat);
    canvas.fillRect(headX - 2, 4, headWidth + 4, 1, PALETTE.hatVillagerDark);
    canvas.fillRect(headX, 0, headWidth, 3, palette.hat);
  }

  canvas.outline(PALETTE.outline);
  return canvas;
}

/** actors.png: (3 frames x 4 facings) per actor, actors side by side. */
export function createActorsSheet() {
  const blockWidth = ACTOR_FRAME_WIDTH * ACTOR_FRAMES;
  const blockHeight = ACTOR_FRAME_HEIGHT * ACTOR_FACINGS.length;
  const sheet = new PixelCanvas(blockWidth * ACTOR_ORDER.length, blockHeight);

  ACTOR_ORDER.forEach((actor, actorIndex) => {
    const originX = actorIndex * blockWidth;
    ACTOR_FACINGS.forEach((facing, row) => {
      if (facing === 'west') {
        // Mirror the east row instead of drawing it twice.
        for (let frame = 0; frame < ACTOR_FRAMES; frame += 1) {
          const east = paintActorFrame(actor, 'east', frame);
          east
            .mirrored()
            .toSheet(sheet, originX + frame * ACTOR_FRAME_WIDTH, row * ACTOR_FRAME_HEIGHT);
        }
        return;
      }
      for (let frame = 0; frame < ACTOR_FRAMES; frame += 1) {
        paintActorFrame(actor, facing, frame).toSheet(
          sheet,
          originX + frame * ACTOR_FRAME_WIDTH,
          row * ACTOR_FRAME_HEIGHT,
        );
      }
    });
  });

  return sheet;
}

/** Darkens (factor < 1) or lightens (factor > 1) a colour, keeping alpha. */
function shade([r, g, b, a], factor) {
  return [
    Math.max(0, Math.min(255, Math.round(r * factor))),
    Math.max(0, Math.min(255, Math.round(g * factor))),
    Math.max(0, Math.min(255, Math.round(b * factor))),
    a,
  ];
}
